class Node {
  constructor(value) {
    this.value = value
    this.next = null
  }
}

class LinkedList {
  constructor(value) {
    this.head = null
    this.tail = null
    this.length = 0
    if (value !== undefined) {
      const firstNode = new Node(value)
      this.head = firstNode
      this.tail = this.head
      this.length = 1
    }
  }

  push(value) {
    const nodeToAdd = new Node(value)
    if (!this.head) {
      this.head = nodeToAdd
      this.tail = nodeToAdd
    } else {
      this.tail.next = nodeToAdd
      this.tail = nodeToAdd
    }
    this.length++
    return this
  }

  reverse() {
    // 1. swap head and tail (current remembers the old head)
    // 2. previous starts as null, and so does nextNode
    // 3. for each node: nextNode = current.next, to remember the rest
    // 4.   current.next = previous: flip the arrow
    // 5.   previous = current, then current = next: both move one node on
    // 6. return the list
  }

  // our helper: the values from head to tail, as an array
  toArray() {
    const values = []
    let current = this.head
    while (current !== null) {
      values.push(current.value)
      current = current.next
    }
    return values
  }
}

